export class PixelFX{
  constructor(root){this.root=root;this.canvas=document.createElement("canvas");this.canvas.className="battle-fx";this.root.appendChild(this.canvas);this.ctx=this.canvas.getContext("2d",{alpha:true});this.raf=0;this.particles=[];this.rings=[];this.running=false;this.resize=()=>this.fit();addEventListener("resize",this.resize,{passive:true});this.fit()}
  fit(){const d=Math.min(2,devicePixelRatio||1),r=this.root.getBoundingClientRect();this.w=r.width;this.h=r.height;this.canvas.width=Math.max(1,Math.floor(r.width*d));this.canvas.height=Math.max(1,Math.floor(r.height*d));this.canvas.style.width=`${r.width}px`;this.canvas.style.height=`${r.height}px`;this.ctx.setTransform(d,0,0,d,0,0);this.ctx.imageSmoothingEnabled=false}
  burst(x,y,colors,count=50,power=1,gravity=.12,inward=false){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=(2+Math.random()*8)*power,d=3+Math.floor(Math.random()*8);this.particles.push({x,y,vx:Math.cos(a)*s*(inward?-1:1),vy:Math.sin(a)*s*(inward?-1:1),life:32+Math.random()*40,max:72,size:d,color:colors[i%colors.length],gravity,inward,targetX:x,targetY:y})}this.start()}
  ring(x,y,color="#ffd04a"){this.rings.push({x,y,r:8,life:24,color});this.start()}
  hit(rect,colors,power=.5){this.burst(rect.x+rect.width/2,rect.y+rect.height/2,colors,Math.round(12+power*16),.55+power*.5,.08);if(power>.7)this.ring(rect.x+rect.width/2,rect.y+rect.height/2,colors[2]||"#ffd04a")}
  start(){if(this.running)return;this.running=true;let last=performance.now();const tick=now=>{const dt=Math.min(2,(now-last)/16.67);last=now;this.ctx.clearRect(0,0,this.w,this.h);for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.gravity*dt;p.vx*=.985;p.life-=dt;if(p.inward){p.x+=(p.targetX-p.x)*.035*dt;p.y+=(p.targetY-p.y)*.035*dt}this.ctx.globalAlpha=Math.max(0,p.life/p.max);this.ctx.fillStyle=p.color;this.ctx.fillRect(Math.round(p.x),Math.round(p.y),p.size,p.size)}this.particles=this.particles.filter(p=>p.life>0);for(const r of this.rings){r.r+=8*dt;r.life-=dt;this.ctx.globalAlpha=Math.max(0,r.life/24);this.ctx.strokeStyle=r.color;this.ctx.lineWidth=5;this.ctx.strokeRect(r.x-r.r/2,r.y-r.r/2,r.r,r.r)}this.rings=this.rings.filter(r=>r.life>0);this.ctx.globalAlpha=1;if(this.particles.length||this.rings.length)this.raf=requestAnimationFrame(tick);else{this.running=false;this.ctx.clearRect(0,0,this.w,this.h)}};this.raf=requestAnimationFrame(tick)}
  async finisher(type,rect,colors){const x=rect.x+rect.width/2,y=rect.y+rect.height/2;this.ring(x,y,colors[2]);if(type==="delete"){for(let i=0;i<6;i++)setTimeout(()=>this.burst(x+(Math.random()-.5)*rect.width,y+(Math.random()-.5)*rect.height,colors,18,.8,0),i*100)}else if(type==="crush"){setTimeout(()=>this.burst(x,y+rect.height*.35,colors,100,1.25,.18),420)}else if(type==="launch"){for(let i=0;i<8;i++)setTimeout(()=>this.burst(x,y+i*9,colors,10,.65,.02),i*70);setTimeout(()=>this.burst(x,32,colors,120,1.5,.04),760)}else if(type==="void"){for(let i=0;i<8;i++)setTimeout(()=>this.burst(x,y,colors,16,1.4,0,true),i*80)}else{for(let i=0;i<4;i++)setTimeout(()=>this.burst(x,y,colors,45,1+i*.25,.11),i*120)}await new Promise(r=>setTimeout(r,1250))}
  destroy(){cancelAnimationFrame(this.raf);removeEventListener("resize",this.resize);this.particles.length=0;this.rings.length=0;if(this.ctx)this.ctx.clearRect(0,0,this.w,this.h);this.canvas.width=0;this.canvas.height=0;this.canvas.remove();this.ctx=null;this.canvas=null;this.running=false}
}
